import numpy as np, json
def f(g):
    g=np.array(g); out=g.copy()
    # find connected components of 5s (4-conn)
    from scipy.ndimage import label
    lab,n=label(g==5)
    for c in range(1,n+1):
        mask=(lab==c); cells=set(zip(*np.where(mask)))
        if len(cells)>=4:
            rs=[r for r,_ in cells]; cs=[c_ for _,c_ in cells]
            h,w=max(rs)-min(rs)+1,max(cs)-min(cs)+1
            sub=out[min(rs):max(rs)+1,min(cs):max(cs)+1].copy()
            for i in range(h):
                for j in range(w):
                    if sub[i,j]==0: sub[i,j]=2
            out[min(rs):max(rs)+1,min(cs):max(cs)+1]=sub
    return out.tolist()
print(json.dumps(f(G['Demo pair 1 input'])))
